// ReadLines reads the file at path and returns its contents as a slice
// of lines, stripping trailing newlines. It returns an error if the
// file cannot be opened or a scan error occurs.
func ReadLines(path string) ([]string, error) {
	f, err := os.Open(path)
	if err != nil {
		return nil, err
	}
	defer f.Close()

	var lines []string
	scanner := bufio.NewScanner(f)
	for scanner.Scan() {
		lines = append(lines, scanner.Text())
	}
	if err := scanner.Err(); err != nil {
		return nil, err
	}
	return lines, nil
}
```

Defers file close immediately after a successful open, and checks scanner.Err() after the loop since bufio.Scanner swallows errors mid-loop and only exposes them afterward.

```c
/* read_int: prompts the user and reads a validated integer.
 * Re-prompts on invalid input instead of returning garbage.
 * Returns the parsed integer. */
int read_int(const char *prompt) {
    char buf[64];
    int value;
    while (1) {
        printf("%s", prompt);
        if (fgets(buf, sizeof(buf), stdin) == NULL) {
            continue;
        }
        if (sscanf(buf, "%d", &value) == 1) {
            return value;
        }
        printf("Invalid input, try again.\n");
    }
}
```

Reads into a fixed buffer with fgets (safer than scanf directly on stdin) and loops until sscanf successfully parses an integer, avoiding undefined behavior from malformed input.

