/* read_int: prompts the user and reads a validated integer.
 * Re-prompts on invalid input instead of returning garbage.
 * Returns the parsed integer. */
int read_int(const char *prompt) {
    char buf[64];
    int value;
    while (1) {
        printf("%s", prompt);
        if (fgets(buf, sizeof(buf), stdin) == NULL) {
            continue;
        }
        if (sscanf(buf, "%d", &value) == 1) {
            return value;
        }
        printf("Invalid input, try again.\n");
    }
}
```

Reads into a fixed buffer with fgets (safer than scanf directly on stdin) and loops until sscanf successfully parses an integer, avoiding undefined behavior from malformed input.

